  str_cn12_n41_levelname_desc1 = "—",
  str_cn12_n41_levelname_desc2 = "Recibes una gran recepción, lo que indica claramente que el gobernante del Reino Ji te tiene en alta estima, sin embargo, el giro de los eventos...",
  str_cn12_n41_levelname_desc3 = "Los estallidos de los fuegos artificiales resuenan por las calles; lo que parecía un simple juego de niños resulta ser algo más...",
  str_cn12_n41_levelname_desc4 = "Surge un conflicto entre los niños y un demonio, aparentemente un asunto trivial hasta que la criatura se vuelve rabiosa...",
  str_cn12_n41_levelname_desc5 = "—",
  str_cn12_n41_levelname_desc6 = "Para descubrir cómo calmar al demonio enloquecido, tú y Luo Song comienzan a buscar a la chica con la que te encontraste antes...",
  str_cn12_n41_levelname_desc7 = "Guiados por tu poder psíquico, el grupo se acerca lentamente a la fuente de la fuerza corrupta en la ciudad—Calle Yulin.",
  str_cn12_n41_levelname_desc8 = "Dentro del palacio, la transacción de cañones costeros entre el Reino de Ji y el Reino de Ye provoca nuevas olas...",
  str_cn12_n41_levelname_desc9 = "Juntos, el líder del gremio Lin y Mu Yuebai te revelan el pasado entre Yoh y la familia Lin...",
  str_cn12_n41_levelname_desc10 = "Unidos, los ciudadanos de la capital deciden expulsar a los demonios de una vez por todas. Con palos y garrotes en mano, se enfrentan a los demonios en las calles.",
  str_cn12_n41_levelname_desc11 = "Dantang, al escabullirse del palacio, se encuentra rodeada por numerosos espías, dejándola incapaz de hacer cualquier movimiento...",
  str_cn12_n41_levelname_desc12 = "Llegas a la bahía y, a pesar de las advertencias de Chen'ni, tú y Mu Yuebai os encontráis abruptamente envueltos por el poder corruptor.",
  str_cn12_n41_levelname_desc13 = "Luo Song y Liqing están trabajando juntos para lidiar con los demonios afectados por el plan de los Fate Riders dentro de la ciudad. Pero de la nada, el cielo se oscurece y olas inmensas oscurecen el cielo...",
  str_cn12_n41_levelname_desc14 = "El oscuro poder que intenta manejar Yoh finalmente se revela, ya que no puede evitar surgir de las profundidades de la mente de Yoh.",
  str_cn12_n41_levelname_desc15 = "—",
  str_cn12_n41_levelname16 = "H1 - Refugio del Daño",
  str_cn12_n41_levelname17 = "H2 - Contra Diabólicos",
  str_cn12_n41_levelname18 = "H3 - Convocar al Dragón",
  str_cn12_n41_levelname19 = "H4 - Erradicado",
  str_cn12_n41_levelname20 = "EX1-1 - Predicar",
  str_cn12_n41_levelname21 = "EX1-2 - Predicar",
  str_cn12_n41_levelname22 = "EX2-1 - Sin miedo",
  str_cn12_n41_levelname23 = "EX2-2 - Sin miedo",
  str_cn12_n41_levelname24 = "EX3-1 - Deseo Concedido",
  str_cn12_n41_levelname25 = "EX3-2 - Deseo Concedido",
  str_cn12_n41_levelname26 = "EX3-3 - Deseo Concedido",
  str_cn12_n41_levelname27 = "EX1 - Predica",
  str_cn12_n41_levelname28 = "EX2 - Sin Miedo",
  str_cn12_n41_levelname29 = "EX3 - Deseo Concedido",
  str_cn12_n41_levelname_desc16 = "Las olas se elevan, la lluvia cae. La gente del pueblo entra en pánico, cerca y lejos.",
  str_cn12_n41_levelname_desc17 = "Dividiendo olas, curando la cicatriz del mal. Doncella dragón, nuestra estrella guía.",
  str_cn12_n41_levelname_desc18 = "Mil años como un suspiro, cien años como una canción. El mundo es testigo de la línea borrosa entre lo correcto y lo incorrecto.",
  str_cn12_n41_levelname_desc19 = "Años despidiéndose, los demonios persisten en la sombra. La gracia de la Doncella Dragón protege todas las direcciones, resplandeciente.",
  str_cn12_n41_levelname_desc20 = "EX1-1 - Predicar: Fuego terrenal",
  str_cn12_n41_levelname_desc21 = "EX1-2 - Predicar: Fuego del cielo",
  str_cn12_n41_levelname_desc22 = "EX2-1 - Fearless: Lluvia",
  str_cn12_n41_levelname_desc23 = "EX2-2 - Sin Miedo: Aguacero",
  str_cn12_n41_levelname_desc24 = "EX3-1 - Deseo Concedido: Caída del Trueno",
  str_cn12_n41_levelname_desc25 = "EX3-2 - Deseo Concedido: Respuesta del Trueno",
  str_cn12_n41_levelname_desc26 = "EX3-3 - Deseo concedido: Choque de trueno",
  str_cn12_n41_1600141_speak = "La riqueza es solo un medio, no el fin. May que esta fortuna te ayude a alcanzar los deseos de tu corazón, maestro del Coloso.",
  str_cn12_n41_1602181_speak = "Tu sorteo auspicioso me trae una alegría sin igual. Honestamente, tus riquezas son, de alguna manera, mis futuras riquezas. ¡Espero con ansias tu próxima visita!",
  str_cn12_n41_1601811_speak = "Estás en la flor de tu vigor, joven amigo. Este palo de la fortuna habla de riqueza, pero la riqueza, las conexiones, las oportunidades y la ambición son inseparables, también es un testimonio de tus habilidades.",
  str_cn12_n41_1601211_speak = "¿Creer que un solo palo de la fortuna puede traer riquezas? ¡Eso es demasiado absurdo! Eh, quizás la magia radica en la creencia. ¡Así que asegúrate de mantener tu ánimo alto!",
  str_cn12_n41_1601121_speak = "¿Fortuna moderada? ¡No está mal! Cuando consigas el dinero, ve a Umbraton y compra ropa elegante, nada más de esos atuendos sencillos.",
  str_cn12_n41_1500761_speak = "Dado que el sueño es lo opuesto a la realidad, quizás lo mismo se aplica a la adivinación, ¿verdad? No te preocupes; ya sea que estés en bancarrota o no, siempre estoy aquí en el mar profundo, esperándote, Navegante.",
  str_cn12_n41_1300531_speak = "¡Oye, jefe, tienes un palo de la fortuna bastante decente! La fortuna moderada es perfecta. ¡Definitivamente ganarás buen dinero el próximo año! ¡Asegúrate de visitar mi tienda a menudo!",
  str_cn12_n41_1500841_speak = "La riqueza significa poder en Umbraton, pero presumir demasiado invita a problemas. El equilibrio es clave, y tu palo de la fortuna parece ser una buena señal.",
  str_cn12_n41_1501871_speak = "Oh, Pequeña Fortuna. Ya la he sacado dos veces, y tú acabas de sacar la última. ¿Deberíamos encontrar una forma de cambiar nuestra suerte?",
  str_cn12_n41_1500331_speak = "Hmm... Fortuna Menor... ¿Podría ser que nuestros gastos diarios aún son demasiado altos? Pero el hecho de que hayamos logrado mantener el Coloso en buen estado y aún tengamos un superávit ya es fantástico! ¡Sigamos con el buen trabajo el próximo año también!",
  str_cn12_n41_1300461_speak = "Deseándote una fortuna, una vida tan grandiosa. En los días venideros, que la alegría se expanda.\nBienvenido lo bueno, y que la desgracia se vaya.\nOfrece regalos en abundancia, y que ningún error te encuentre.\n¡La pequeña fortuna sigue siendo fortuna! ¡Asegúrate de poner más en el sobre rojo para mí!",
  str_cn12_n41_1600771_speak = "Tienes el poder de moldear el destino del mundo, por lo que este resultado es de esperarse. No te preocupes; estaré contigo en cada paso del camino.",
  str_cn12_n41_1602161_speak = "En Longzhou, decimos que los héroes son \"Bendecidos por el Cielo\", o \"Líderes Nacidos, Destinados por los Cielos y la Tierra\". Como hablamos en la Sala de Recreo, eres exactamente así, siempre convirtiendo las desgracias en bendiciones, ¿no crees?",
  str_cn12_n41_1601531_speak = "Parece que estás listo para lograr grandes cosas este año. Solo ten en cuenta que cuanto más alto vayas, más debes estar alerta, ya sabes, los árboles grandes atrapan más viento. Y no olvides buscar ayuda de tus socios de confianza cuando sea necesario.",
  str_cn12_n41_1601171_speak = "¡Jaja, tu expresión lo dice todo! Es bueno que los jóvenes tengan grandes aspiraciones. Pero recuerda, además de la batalla y el entrenamiento, la salud también importa. ¿Quieres un poco de sopa enlatada?",
  str_cn12_n41_1601191_speak = "Grandes visiones... ¿qué es eso? ¿Significa este palo de la fortuna que serás más fuerte contra los Eclipsites? Pero oye, el mío dice \"Gran Fortuna\". Jeje, eso es mucho más impresionante que el tuyo, ¿no es así?",
  str_cn12_n41_1600061_speak = "Un resultado satisfactorio, no tan desalentador, pero suficiente para encender tu espíritu de lucha por un futuro más brillante. Espero tener un papel en esa versión de tu futuro.",
  str_cn12_n41_1600021_speak = "Todo en este mundo es inherentemente vacío. Tal conciencia es lo que ayuda a uno a romper sus propios límites. May nuestros destinos sean nuestros propios para comandar.",
  str_cn12_n41_1601291_speak = "Parece que la suerte está de tu lado, querido compañero. ¿Qué, aún no estás satisfecho? Una vez que termine con esta misión, te haré un dibujo aún más fino de la Gran Fortuna.",
  str_cn12_n41_1600641_speak = "Felicidades, obtuviste lo mismo que yo, una Pequeña Fortuna sigue siendo una fortuna, ¿no es así? ¡Estamos destinados a cambiar las cosas este año! Espera, ¿por qué estás haciendo un Namaste así?",
  str_cn12_n41_1600301_speak = "Te dije que te quedaras conmigo, chico. ¡Nadie puede definir tu éxito excepto tú mismo! Vive el momento y vive la vida al máximo.",
  str_cn12_n41_1500551_speak = "Las varillas de la fortuna son solo para divertirse, así que no vengas a preguntarme cómo pasar toda la noche despierto. ¿Qué tal si te enfocas primero en ponerte en forma, paso a paso?",
  str_cn12_n41_1601881_speak = "Tu palo dice Gran Fortuna, lo que significa que la suerte debe estar de tu lado. Espera, también dice que tu alma gemela está justo delante de ti... pero solo somos nosotros dos aquí, ¡la adivinación de Li Tianxian es una total farsa!",
  str_cn12_n41_1602111_speak = "¡No puedo creer que tu vida amorosa sea tan prometedora! \"¿Tu pareja destinada puede estar justo entre tus compañeros\"? Hmm...me emociona un poco nuestro próximo viaje, ¡solo un poco!",
  str_cn12_n41_1601161_speak = "¡Parece que te estás volviendo más popular que yo estos días! Pero oye, ser demasiado popular no siempre es genial, así que cuídate. ¡Y si alguna vez necesitas escapar de alguna situación, mi nuevo Steel Wing V2 está a tu disposición!",
  str_cn12_n41_1601311_speak = "¡Felicidades, Su Excelencia! Encontrar a alguien con quien quedarse y recorrer la vida juntos es algo realmente conmovedor y afortunado.",
  str_cn12_n41_1601261_speak = "Las historias de amor en la ficción siempre comienzan como un sueño, son divertidas de principio a fin y tienen un final feliz. Creo que tu vida amorosa será tan perfecta como esas historias.",
  str_cn12_n41_1500991_speak = "El valor que le damos a los demás nos hace dudar en acercarnos a ellos, dudando si alguna vez podremos tenerlos... Pero a veces debes ser valiente, acercarte, extender la mano, para ser feliz, ¿verdad?",
  str_cn12_n41_1600261_speak = "¿Cuál es el significado de todo esto? De todos modos, todo es vacío... ¿Qué, quieres compartir esta buena fortuna conmigo?... De repente tengo esta extraña sensación... Está bien, dime qué palo de la fortuna sacaste.",
  str_cn12_n41_1601111_speak = "No tener miedo de acercarse y establecer conexiones con los demás ya es una gran bendición y alegría... ¿Puedo yo también encontrar esa alegría simple?",
  str_cn12_n41_1602121_speak = "¡El texto en los palos de la fortuna, incluso aquellos con esperanzas depositadas en ellos, puede interpretarse racionalmente! Pero mi investigación en psicología es insuficiente... Es hora de ir a la biblioteca a buscar algunos materiales de psicología romántica... ¡Ups, lo siento, estoy pensando en voz alta otra vez!",
  str_cn12_n41_1601051_speak = "Después de decir que aún no soy lo suficientemente mayor para estas cosas, mi hermano salió enfadado con su llave inglesa. ¿Puedes decirme si lo ves? Gracias, ¡eres el mejor!",
  str_cn12_n41_1501831_speak = "Siendo el mayor aquí, obtuve la misma varita de la fortuna que tú. Pero oye, deberías preocuparte más por la buena comida y mantenerse saludable. ¿Ves? Incluso Tinytail está de acuerdo, moviendo su cola y todo.",
  str_cn12_n41_litianxian_speak1 = "¡Ah, aquí vienes! Recientemente, me he encontrado con un exquisito conjunto de palos de la fortuna. Se dice que el deseo de uno se revelará en el mensaje del palo. ¿Te gustaría probar la suerte de hoy?",
  str_cn12_n41_litianxian_speak2 = "¡Gracias por tu patrocinio! ¡May todos tus deseos se hagan realidad! Por favor, regresa otro día, ¡y entonces podremos discutir las fortunas juntos!",
  str_cn12_n41_game_title_tip = "Por favor, seleccione la fortuna que desea recibir.",
  str_cn12_n41_game_luck3 = "Gran Fortuna",
  str_cn12_n41_game_luck2 = "Fortuna moderada",
  str_cn12_n41_game_luck1 = "Fortuna Menor",
  str_cn12_n41_game_luck_none = "No Dibujado",
  str_cn12_n41_game_tip1 = "Cada día, puedes hacer 3 sorteos, de los cuales solo un resultado puede ser reclamado como recompensa.",
  str_cn12_n41_game_tip2 = "Restante hoy: {1}",
  str_cn12_n41_game_tip3 = "Por favor, seleccione el aspecto en el que se predecirá su fortuna.",
  str_cn12_n41_game_tip4 = "¿Confirmar para seleccionar <color=#962b1c>{1}</color>?",
  str_cn12_n41_game_tip5 = "Por favor, selecciona un aspecto.",
