  str_cn12_n41_game_end_btn = "Listo",
  str_cn12_n41_luck_bag_intro_title = "Información del evento Fortune Beckons",
  str_cn12_n41_luck_bag_intro_head_1 = "La Adivinación",
  str_cn12_n41_luck_bag_intro_body_1 = "Cada día, puedes elegir predecir tu fortuna en uno de los siguientes 3 aspectos: Riqueza, Amor y Perspectivas.\nDespués de decidir sobre el aspecto de la adivinación, puedes hacer 3 tiradas cada día para obtener orientación adivinatoria. Los intentos de tirada se renuevan diariamente.\nLos resultados de la tirada incluyen Gran Fortuna, Fortuna Moderada y Pequeña Fortuna, uno de los cuales será elegido al azar y presentado.",
  str_cn12_n41_luck_bag_intro_head_2 = "Seleccionando Fortuna",
  str_cn12_n41_luck_bag_intro_body_2 = "Cada día, puedes elegir recibir una fortuna de los sorteos que has hecho.\nAceptar una fortuna te otorga su recompensa correspondiente.\nSolo se puede aceptar 1 fortuna cada día. Una vez que se acepta una fortuna, otras fortunas y sus recompensas correspondientes se consideran como perdidas.",
